import { writeFileSync } from "node:fs";
import { CATEGORY_LABELS, REGION_CATEGORIES } from "../src/shared/constants";
import { REGION_BANK } from "../src/server/data/regionBank";

const level = { 1: "easy", 2: "medium", 3: "hard" } as const;
const lines: string[] = [
  "# Region questions",
  "",
  "All region questions with their correct answers, for review. Generated by `npx tsx scripts/exportRegionQuestions.ts`. Edit the questions in `src/server/data/regionBank.ts`.",
  "",
];
for (const c of REGION_CATEGORIES) {
  lines.push(`## ${CATEGORY_LABELS[c]}`, "");
  REGION_BANK[c].forEach((r, i) => {
    lines.push(`${i + 1}. (${level[r[0]]}) ${r[1]}`);
    lines.push(`   - Answer: ${r[2]}`);
    lines.push(`   - Other options: ${r[3]}, ${r[4]}, ${r[5]}`);
  });
  lines.push("");
}
writeFileSync("docs/REGION_QUESTIONS.md", lines.join("\n"));
console.log("written");
